#!/usr/bin/env python3
# fix_max_tokens.py

import json
import os
import shutil
import sys


CORRECT_LIMITS = {
    "gpt-4o": 16384,
    "gpt-4o-mini": 16384,
    "o3-mini": 65536,
    "claude-opus-4": 8096,
    "claude-sonnet-4": 8096,
    "claude-haiku-3-5": 8096,
    "gemini-2.0-flash": 8192,
    "mistral-large": 131072,
    "llama-3.3-70b": 8192,
    "phi-3-mini-128k": 4096,
}


def parse_args(argv):
    dry_run = False
    config_path = None

    for arg in argv[1:]:
        if arg == "--dry-run":
            dry_run = True
        elif config_path is None:
            config_path = arg
        else:
            print(f"Warning: ignoring extra argument: {arg}", file=sys.stderr)

    if config_path is None:
        config_path = "~/.openclaw/config.json"

    return config_path, os.path.expanduser(config_path), dry_run


def format_value(value):
    if value is None:
        return "<missing>"
    return str(value)


def load_config(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: config file not found: {path}", file=sys.stderr)
    except json.JSONDecodeError as e:
        print(f"Error: failed to parse JSON in {path}: {e}", file=sys.stderr)
    except OSError as e:
        print(f"Error: unable to read {path}: {e}", file=sys.stderr)
    return None


def save_config(path, config):
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(config, f, indent=2)
            f.write("\n")
        return True
    except OSError as e:
        print(f"Error: failed to write config to {path}: {e}", file=sys.stderr)
        return False


def create_backup(path):
    backup_path = path + ".bak"
    try:
        shutil.copy2(path, backup_path)
        return backup_path
    except OSError as e:
        print(f"Error: failed to create backup at {backup_path}: {e}", file=sys.stderr)
        return None


def main():
    display_path, config_path, dry_run = parse_args(sys.argv)
    config = load_config(config_path)
    if config is None:
        return 1

    models = config.get("models")
    if not isinstance(models, list):
        print("Error: invalid config format: 'models' must be a list", file=sys.stderr)
        return 1

    updated = 0
    unchanged = 0
    skipped = 0

    print(f"Checking {len(models)} models...")

    for index, model in enumerate(models):
        if not isinstance(model, dict):
            print(f"  model[{index}]: invalid model entry (skipped)")
            skipped += 1
            continue

        model_id = model.get("id")
        if not model_id:
            print(f"  model[{index}]: missing model id (skipped)")
            skipped += 1
            continue

        if model_id not in CORRECT_LIMITS:
            print(f"  {model_id}: unknown model ID (skipped)")
            skipped += 1
            continue

        correct_value = CORRECT_LIMITS[model_id]
        current_value = model.get("maxTokens")

        if current_value == correct_value:
            print(f"  {model_id}: {format_value(current_value)} → {correct_value} (no change)")
            unchanged += 1
        else:
            status = "WOULD UPDATE" if dry_run else "UPDATED"
            print(f"  {model_id}: {format_value(current_value)} → {correct_value} ({status})")
            updated += 1
            if not dry_run:
                model["maxTokens"] = correct_value

    print()
    print(f"Summary: {updated} updated, {unchanged} unchanged, {skipped} skipped")

    if dry_run:
        print("Dry run: no changes written.")
        return 0

    if updated == 0:
        print("No changes needed; config not modified.")
        return 0

    backup_path = create_backup(config_path)
    if backup_path is None:
        return 1

    if not save_config(config_path, config):
        return 1

    print(f"Backup saved to: {display_path}.bak")
    print(f"Config saved to: {display_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
